package lk.gov.health.govcare.ai;
import lk.gov.health.govcare.common.*;import lk.gov.health.govcare.security.*;import org.springframework.stereotype.Service;import java.util.*;import static lk.gov.health.govcare.ai.AiRiskDtos.*;
@Service public class AiRiskService{private final SqlSupport sql;private final JsonSupport json;private final DeteriorationRiskEngine engine;private final ClinicalPatientAccess access;public AiRiskService(SqlSupport s,JsonSupport j,DeteriorationRiskEngine e,ClinicalPatientAccess access){sql=s;json=j;engine=e;this.access=access;}
 public Map<String,Object>dashboard(GovCarePrincipal a){var visible=access.visiblePatientIds(a);if(visible.isEmpty())return Map.of("summary",Map.of("total",0,"alerts",0,"reviewed",0),"items",List.of(),"modelVersion","GOVCARE-DETERIORATION-RULES-1.0");var items=sql.list("select x.id::text,x.patient_id::text \"patientId\",p.patient_no \"patientNumber\",p.full_name \"patientName\",x.score,x.risk_level \"riskLevel\",x.confidence,x.contributing_factors factors,x.recommendation,x.status,x.created_at \"createdAt\",x.reviewed_at \"reviewedAt\",x.review_note \"reviewNote\" from ai_deterioration_assessments x join patients p on p.id=x.patient_id where (:network or x.hospital_id=:hospital) and x.patient_id in (:visible) order by x.created_at desc limit 100",listParams(a,visible));var summary=sql.required("select count(*)::int total,count(*) filter(where risk_level in('HIGH','CRITICAL') and status='OPEN')::int alerts,count(*) filter(where status='REVIEWED')::int reviewed from ai_deterioration_assessments where (:network or hospital_id=:hospital) and patient_id in (:visible)",listParams(a,visible),"Unable to load AI summary.");return Map.of("summary",summary,"items",items,"modelVersion","GOVCARE-DETERIORATION-RULES-1.0");}
 public List<Map<String,Object>>patients(GovCarePrincipal a){var visible=access.visiblePatientIds(a);if(visible.isEmpty())return List.of();return sql.list("select id::text,patient_no \"patientNumber\",full_name \"patientName\" from patients where (:network or hospital_id=:hospital) and id in (:visible) and status<>'deleted' order by updated_at desc limit 100",listParams(a,visible));}
 public Map<String,Object>assess(GovCarePrincipal a,AssessmentRequest q){UUID patient=sql.uuid(q.patientId(),"patientId");a=access.clinicalScope(a,patient,true);sql.required("select id from patients where id=:patient and hospital_id=:hospital and status<>'deleted'",Map.of("patient",patient,"hospital",a.hospitalId()),"Patient not found.");ScoreResult r;try{r=engine.score(q);}catch(IllegalArgumentException e){throw ApiException.badRequest(e.getMessage());}Map<String,Object>p=new HashMap<>();p.put("hospital",a.hospitalId());p.put("patient",patient);p.put("score",r.score());p.put("risk",r.riskLevel());p.put("confidence",r.confidence());p.put("input",json.write(r.inputs()));p.put("factors",json.write(r.factors()));p.put("recommendation",r.recommendation());p.put("actor",a.id());var saved=sql.required("insert into ai_deterioration_assessments(hospital_id,patient_id,score,risk_level,confidence,input_data,contributing_factors,recommendation,model_version,created_by) values(:hospital,:patient,:score,:risk,:confidence,cast(:input as jsonb),cast(:factors as jsonb),:recommendation,'GOVCARE-DETERIORATION-RULES-1.0',:actor) returning id::text",p,"Unable to save risk assessment.");return sql.required("select x.id::text,x.patient_id::text \"patientId\",p.patient_no \"patientNumber\",p.full_name \"patientName\",x.score,x.risk_level \"riskLevel\",x.confidence,x.contributing_factors factors,x.recommendation,x.status,x.created_at \"createdAt\" from ai_deterioration_assessments x join patients p on p.id=x.patient_id where x.id=cast(:id as uuid)",Map.of("id",saved.get("id")),"Assessment not found.");}
 public Map<String,Object>review(GovCarePrincipal a,String id,ReviewRequest q){Map<String,Object> lookup=new HashMap<>();lookup.put("id",id);lookup.put("hospital",a.hospitalId());lookup.put("network",access.canAccessNetwork(a));var identity=sql.required("select patient_id from ai_deterioration_assessments where id=cast(:id as uuid) and (:network or hospital_id=:hospital)",lookup,"Assessment not found.");a=access.clinicalScope(a,(UUID)identity.get("patient_id"),true);var row=sql.required("select patient_id from ai_deterioration_assessments where id=cast(:id as uuid) and hospital_id=:hospital",Map.of("id",id,"hospital",a.hospitalId()),"Assessment not found.");access.requireClinicalWrite(a,(UUID)row.get("patient_id"));int n=sql.update("update ai_deterioration_assessments set status='REVIEWED',reviewed_by=:actor,reviewed_at=now(),review_note=:note where id=cast(:id as uuid) and hospital_id=:hospital",Map.of("actor",a.id(),"note",q.note()==null?"":q.note().trim(),"id",id,"hospital",a.hospitalId()));if(n==0)throw ApiException.notFound("Assessment not found.");return Map.of("status","REVIEWED");} private Map<String,Object> listParams(GovCarePrincipal a,List<UUID> visible){Map<String,Object> p=new HashMap<>();p.put("hospital",a.hospitalId());p.put("h",a.hospitalId());p.put("visible",visible);p.put("network",access.canAccessNetwork(a));return p;}
}
